import { getPsychologyState, submitGate, evaluateRules, getMarketSnapshots, getMacroNarrative, evaluateQuality } from '../lib/api';
import type { MarketSnapshot, UnifiedQualityResult } from '../lib/types';

// ── Psychology gate questions (mirrors backend gate-questions.ts ids 1-5) ──
const GATE_QS = [
  { id:1, question:'هل لديك خطة تداول واضحة ومكتوبة لهذه الصفقة؟',
    options:[{label:'نعم، خطة واضحة مع نقاط الدخول والخروج'},{label:'عندي فكرة عامة بس مو مكتوبة'},{label:'لا، أشوف الشارت وأدخل على حسب الإحساس'}]},
  { id:2, question:'ما هو الحالة النفسية الحالية لديك؟',
    options:[{label:'هادي ومتركز — جاهز للتنفيذ'},{label:'متوتر شوي بس أقدر أتحكم'},{label:'عصبي أو خايف أو متحمس زيادة'}]},
  { id:3, question:'هل راجعت آخر 5 صفقات واستخلصت الدروس؟',
    options:[{label:'نعم، راجعتها وكتبت ملاحظاتي'},{label:'عندي فكرة بس ما كتبت شي'},{label:'لا، ما راجعت'}]},
  { id:4, question:'هل انتظرت تأكيد الشمعة أم تدخل على أمل؟',
    options:[{label:'انتظرت الإغلاق والتأكيد'},{label:'دخلت بنص شمعة بس الإشارة واضحة'},{label:'دخلت فزعة أخاف يفوتني'}]},
  { id:5, question:'هل حددت وقف الخسارة قبل الدخول؟',
    options:[{label:'نعم، محدد ومكتوب'},{label:'عندي منطقة تقريبية'},{label:'لا، أشوف السوق وأقرر'}]},
];
const C = {
  bg:'#0f0e0c', card:'#181614', card2:'#211e1a', bg3:'#0b0a09',
  green:'#2bb57e', gold:'#c9924a', red:'#ef4444', amber:'#f59e0b',
  t1:'#ede8e3', t2:'#9a9086', t3:'#5a5045',
  border:'rgba(201,146,74,0.10)', border2:'rgba(255,255,255,0.07)',
} as const;

// ── types ──
type Trend = 'bullish' | 'bearish' | 'neutral';
type Location = 'discount' | 'equilibrium' | 'premium';

interface TrilInput { trend: Trend; raid: boolean; imbalance: boolean; location: Location; orderBlock: boolean; immediateRebalance: boolean; }
interface TrilResult { trend: boolean; raid: boolean; imbalance: boolean; location: boolean; orderBlock: boolean; immediateRebalance: boolean; }
interface ConstitutionInput {
  tradesTaken: number; riskAmount: number; rrr: number;
  dailyPnl: number; consecLosses: number; dayOfWeek: number;
}
interface Verdict { verdict: string; ar: string; color: string; reason: string; }

// ── THEEB CONSTITUTION — overrides everything ──
const CONSTITUTION = {
  MAX_TRADES_PER_DAY: 2, MAX_RISK_PER_TRADE: 500, MIN_RRR: 2.5,
  DAILY_LOSS_LIMIT: 600, CONSECUTIVE_LOSS_LIMIT: 2, NO_TRADE_DAYS: [3, 5],
} as const;

function checkConstitution(i: ConstitutionInput): string[] {
  const v: string[] = [];
  if (i.tradesTaken >= CONSTITUTION.MAX_TRADES_PER_DAY) v.push('تجاوزت الحد الأقصى للصفقات اليومية (2)');
  if (i.riskAmount > CONSTITUTION.MAX_RISK_PER_TRADE) v.push('المخاطرة تتجاوز $500 المسموحة');
  if (i.rrr < CONSTITUTION.MIN_RRR) v.push('نسبة الربح/الخسارة أقل من 2.5');
  if (i.dailyPnl <= -CONSTITUTION.DAILY_LOSS_LIMIT) v.push('تجاوزت حد الخسارة اليومي ($600)');
  if (i.consecLosses >= CONSTITUTION.CONSECUTIVE_LOSS_LIMIT) v.push('خسارتان متتاليتان — توقف إلزامي');
  if ((CONSTITUTION.NO_TRADE_DAYS as readonly number[]).includes(i.dayOfWeek)) v.push('يوم ممنوع من التداول (الأربعاء/الجمعة)');
  return v;
}

function checkTRIL(i: TrilInput): TrilResult {
  return {
    trend: i.trend !== 'neutral', raid: i.raid, imbalance: i.imbalance,
    location: i.location !== 'equilibrium', orderBlock: i.orderBlock, immediateRebalance: i.immediateRebalance,
  };
}

function getVerdict(trilPass: TrilResult, violations: string[]): Verdict {
  if (violations.length > 0)
    return { verdict:'DO NOT TRADE', ar:'لا تتداول', color:C.red, reason:violations[0] };
  const n = Object.values(trilPass).filter(Boolean).length;
  if (n >= 5) return { verdict:'SAFE TO TRADE', ar:'آمن للتداول', color:C.green, reason:'كل عوامل TRIL متوافقة والدستور سليم' };
  if (n >= 3) return { verdict:'CAUTION', ar:'تحفّظ', color:C.amber, reason:n+'/6 من TRIL متوافقة' };
  return { verdict:'DO NOT TRADE', ar:'لا تتداول', color:C.red, reason:'بنية الشارت غير متوافقة' };
}

function getCoach(verdict: Verdict, trilPass: TrilResult, violations: string[]): string[] {
  if (violations.length > 0)
    return ['القرار متوقف بسبب مخالفة الدستور.', violations[0]+'.', 'لا استثناءات على هذه القاعدة.'];
  if (verdict.verdict === 'SAFE TO TRADE') {
    const l: string[] = ['الاتجاه متوافق مع الفكرة.'];
    if (trilPass.raid) l.push('تم سحب السيولة قبل الدخول.');
    if (trilPass.orderBlock) l.push('كتلة الأوامر تدعم منطقة الدخول.');
    if (trilPass.immediateRebalance) l.push('إعادة التوازن الفوري متوفرة — تأكيد إضافي.');
    if (trilPass.location) l.push('الموقع ضمن منطقة الاهتمام الصحيحة.');
    l.push('المخاطرة ضمن الحدود المسموحة.');
    return l.slice(0, 4);
  }
  const f: string[] = [];
  if (!trilPass.trend) f.push('الاتجاه غير واضح');
  if (!trilPass.raid) f.push('السيولة لم تُسحب بعد');
  if (!trilPass.imbalance) f.push('لا يوجد عدم توازن واضح (FVG/OB)');
  if (!trilPass.orderBlock) f.push('كتلة الأوامر غير مؤكدة');
  if (!trilPass.immediateRebalance) f.push('إعادة التوازن الفوري غير متوفر');
  if (!trilPass.location) f.push('الموقع في منطقة محايدة');
  const missing = f.length > 0 ? f[0]+'.' : 'راجع عوامل TRIL.';
  return ['القرار يحتاج مراجعة قبل التنفيذ.', missing, 'انتظر تأكيداً أوضح قبل الدخول.'];
}

// ── atoms ──
function TrilRow({ label, en, pass }: { label: string; en: string; pass: boolean }) {
  const c = pass ? C.green : C.red;
  return(
    <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',padding:'9px 0',borderBottom:'1px solid '+C.border2}}>
      <div>
        <div style={{fontSize:13,fontWeight:700,color:C.t1}}>{label}</div>
        <div style={{fontSize:9,color:C.t3,fontFamily:'JetBrains Mono',letterSpacing:'.05em'}}>{en}</div>
      </div>
      <div style={{width:26,height:26,borderRadius:8,background:c+'15',border:'1px solid '+c+'40',display:'flex',alignItems:'center',justifyContent:'center'}}>
        <span style={{fontSize:14,color:c,fontWeight:800}}>{pass?'✓':'✕'}</span>
      </div>
    </div>
  );
}

function Toggle({ label, active, onToggle }: { label: string; active: boolean; onToggle: () => void }) {
  return(
    <button onClick={onToggle} style={{padding:'5px 11px',borderRadius:7,border:'1px solid '+(active?C.green+'40':C.border2),
      background:active?'rgba(0,214,143,.08)':'transparent',color:active?C.green:C.t3,fontSize:10,fontFamily:'JetBrains Mono',fontWeight:700}}>
      {label}
    </button>
  );
}

export default function TheebMindGate() {
  const [time,setTime]=useState('');
  const [symbol,setSymbol]=useState('OANDA:NAS100USD');
  const [ivl,setIvl]=useState('15');
  const [trend,setTrend]=useState<Trend>('bullish');
  const [raid,setRaid]=useState(true);
  const [imbalance,setImbalance]=useState(true);
  const [location,setLocation]=useState<Location>('discount');
  const [tradesTaken,setTradesTaken]=useState(1);
  const [riskAmount,setRiskAmount]=useState(500);
  const [rrr,setRrr]=useState(2.5);
  const [dailyPnl]=useState(245);
  const [consecLosses,setConsecLosses]=useState(0);

  // Zone / level notes
  const [zoneTag,setZoneTag]=useState<string[]>([]);
  const [zonePrice,setZonePrice]=useState('');
  const [zoneNote,setZoneNote]=useState('');
  const [savedZones,setSavedZones]=useState<Array<{id:number;tags:string[];price:string;note:string;time:string}>>(()=>{
    try{return JSON.parse(localStorage.getItem('theeb-zones')||'[]');}catch{return[];}
  });

  const [orderBlock,setOrderBlock]=useState(false);
  const [immediateRebalance,setImmediateRebalance]=useState(false);
  // Psychology gate
  const [psychVerdict,setPsychVerdict]=useState<'STOP'|null>(null);
  const [gateChecked,setGateChecked]=useState(false);
  const [showGateForm,setShowGateForm]=useState(false);
  const [gateAnswers,setGateAnswers]=useState<Record<number,number>>({});
  const [gateSubmitting,setGateSubmitting]=useState(false);

  // Rule violations — async backend evaluation with local fallback
  const [backendViolations,setBackendViolations]=useState<string[]|null>(null);

  // Market Intelligence — live snapshots + macro narrative
  const [mktSnaps,setMktSnaps]=useState<MarketSnapshot[]>([]);
  const [macroNarr,setMacroNarr]=useState<string>('');

  // Live quality score from the real scoring engine
  const [apiQuality,setApiQuality]=useState<UnifiedQualityResult|null>(null);

  const trendCycle: Trend[] = ['bullish','bearish','neutral'];
  const locCycle: Location[] = ['discount','equilibrium','premium'];

  useEffect(()=>{
    const t=()=>setTime(new Date().toLocaleTimeString('en-US',{timeZone:'America/New_York',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}));
    t();const i=setInterval(t,1000);return()=>clearInterval(i);
  },[]);

  useEffect(()=>{
    getPsychologyState('user-1')
      .then(s=>{ setPsychVerdict(s.riskTolerance==='high'?'STOP':null); setGateChecked(true); })
      .catch(()=>setGateChecked(true));
  },[]);

  // Load live market snapshots + macro narrative on mount
  useEffect(()=>{
    getMarketSnapshots().then(s=>setMktSnaps(s)).catch(()=>{});
    getMacroNarrative('user-1').then(n=>setMacroNarr(n?.narrativeText??'')).catch(()=>{});
  },[]);

  // Debounced live quality evaluation via the real scoring engine
  useEffect(()=>{
    const timer=setTimeout(async()=>{
      try{
        const result=await evaluateQuality({
          marketStructure: trend!=='neutral',
          fairValueGap:    imbalance,
          orderBlock,
          liquiditySweep:  raid,
          killzoneActive:  false,
          immediateRebalance,
          gatePercentage:  psychVerdict===null ? 80 : 30,
          gateVerdict:     psychVerdict===null ? 'pass' : 'fail',
          behavioralLock:  psychVerdict==='STOP',
          psychPhase:      'green',
          rrr,
          rrrPass:         rrr>=2.5,
          riskAmount,
          tradeCountToday: tradesTaken,
          isPreMarket:     false,
          consecutiveLosses: consecLosses,
          isNoTradeDay:    false,
          alignmentScore:  75,
        });
        setApiQuality(result);
      }catch{ /* keep local fallback */ }
    },400);
    return()=>clearTimeout(timer);
  },[trend,raid,imbalance,orderBlock,immediateRebalance,rrr,riskAmount,tradesTaken,consecLosses,psychVerdict]);

  // Debounced backend rule evaluation — persists violations for audit trail
  useEffect(()=>{
    const timer=setTimeout(async()=>{
      try{
        const result=await evaluateRules({tradesTaken,riskAmount,rrr,dailyPnl,consecLosses,dayOfWeek:new Date().getDay()});
        setBackendViolations(result.warnings);
      }catch{
        // Network error — clear stale backend result so local checkConstitution is used
        setBackendViolations(null);
      }
    },300);
    return()=>clearTimeout(timer);
  },[tradesTaken,riskAmount,rrr,dailyPnl,consecLosses]);

  async function handleGateSubmit(){
    setGateSubmitting(true);
    try{
      const answers=Object.entries(gateAnswers).map(([qid,optIdx])=>({
        questionId:'q'+qid,
        answer:optIdx===0?'نعم':optIdx===1?'لا':'غير متأكد',
      }));
      const result=await submitGate(answers);
      setPsychVerdict(result.verdict==='STOP'?'STOP':null);
      setShowGateForm(false);
    }catch{ setShowGateForm(false); }
    finally{ setGateSubmitting(false); }
  }

  const dow = new Date().getDay();
  const trilPass = checkTRIL({trend,raid,imbalance,location,orderBlock,immediateRebalance});
  // Use backend violations when available; fall back to local for instant response
  const violations = backendViolations ?? checkConstitution({tradesTaken,riskAmount,rrr,dailyPnl,consecLosses,dayOfWeek:dow});
  const verdict = getVerdict(trilPass, violations);
  const coach = getCoach(verdict, trilPass, violations);

  return(
    <div className="tm-root" style={{height:'100%',minHeight:0,display:'flex',flexDirection:'column',background:C.bg,color:C.t1,fontFamily:"'Cairo',sans-serif",direction:'rtl',overflow:'hidden',position:'relative'}}>
      {/* ── Psychology STOP gate overlay ── */}
      {gateChecked && psychVerdict==='STOP' && !showGateForm && (
        <div style={{position:'absolute',inset:0,zIndex:200,background:'rgba(4,6,10,0.97)',display:'flex',flexDirection:'column',alignItems:'center',justifyContent:'center',gap:20,padding:24,textAlign:'center'}}>
          <div style={{width:56,height:56,borderRadius:16,background:C.red+'18',border:'2px solid '+C.red+'40',display:'flex',alignItems:'center',justifyContent:'center',fontSize:26,color:C.red}}>✕</div>
          <div>
            <div style={{fontFamily:'JetBrains Mono',fontSize:9,color:C.red,letterSpacing:'.22em',marginBottom:10}}>PSYCHOLOGY GATE — STOP</div>
            <div style={{fontSize:20,fontWeight:900,color:C.t1,marginBottom:10}}>البوابة النفسية مغلقة</div>
            <div style={{fontSize:13,color:C.t2,lineHeight:1.8,maxWidth:360}}>نتيجة آخر فحص نفسي تمنع التداول الآن. التداول بدون جاهزية نفسية يضاعف الخسائر.</div>
          </div>
          <button onClick={()=>setShowGateForm(true)} style={{padding:'12px 28px',borderRadius:10,background:C.gold+'18',border:'1px solid '+C.gold+'50',color:C.gold,fontSize:14,fontWeight:700,cursor:'pointer'}}>أجب على أسئلة البوابة النفسية</button>
        </div>
      )}
      {/* ── Inline psychology gate form ── */}
      {showGateForm && (
        <div style={{position:'absolute',inset:0,zIndex:200,background:'rgba(4,6,10,0.97)',overflow:'auto',padding:'20px 16px',direction:'rtl'}}>
          <div style={{maxWidth:520,margin:'0 auto'}}>
            <div style={{fontFamily:'JetBrains Mono',fontSize:9,color:C.gold,letterSpacing:'.2em',marginBottom:14}}>PSYCHOLOGY GATE — ASSESSMENT</div>
            <div style={{fontSize:18,fontWeight:900,color:C.t1,marginBottom:4}}>فحص الجاهزية النفسية</div>
            <div style={{fontSize:12,color:C.t2,marginBottom:20,lineHeight:1.7}}>أجب بصدق — نتيجتك تحدد جاهزيتك للتداول</div>
            {GATE_QS.map(q=>(
              <div key={q.id} style={{marginBottom:14,padding:'12px',borderRadius:10,background:C.card2,border:'1px solid '+C.border}}>
                <div style={{fontSize:13,fontWeight:700,color:C.t1,marginBottom:10,lineHeight:1.6}}>{q.id}. {q.question}</div>
                <div style={{display:'flex',flexDirection:'column',gap:6}}>
                  {q.options.map((opt,idx)=>(
                    <button key={idx} onClick={()=>setGateAnswers(prev=>({...prev,[q.id]:idx}))} style={{
                      padding:'8px 12px',borderRadius:7,textAlign:'right',fontSize:12,lineHeight:1.5,cursor:'pointer',
                      border:'1px solid '+(gateAnswers[q.id]===idx?C.gold+'60':C.border2),
                      background:gateAnswers[q.id]===idx?C.gold+'12':'transparent',
                      color:gateAnswers[q.id]===idx?C.t1:C.t2,
                    }}>{opt.label}</button>
                  ))}
                </div>
              </div>
            ))}
            <button
              disabled={Object.keys(gateAnswers).length<5||gateSubmitting}
              onClick={handleGateSubmit}
              style={{
                width:'100%',padding:'14px',borderRadius:10,marginTop:8,cursor:'pointer',
                background:Object.keys(gateAnswers).length>=5&&!gateSubmitting?C.green+'18':'rgba(255,255,255,0.03)',
                border:'1px solid '+(Object.keys(gateAnswers).length>=5?C.green+'40':C.border2),
                color:Object.keys(gateAnswers).length>=5&&!gateSubmitting?C.green:C.t3,
                fontSize:14,fontWeight:700,
              }}
            >{gateSubmitting?'جاري التقييم...':'إرسال التقييم'}</button>
          </div>
        </div>
      )}
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Tajawal:wght@400;500;700;800;900&family=JetBrains+Mono:wght@400;500;600;700;800&display=swap');
        *{margin:0;padding:0;box-sizing:border-box}
        @keyframes pulse{0%,100%{opacity:1}50%{opacity:.15}}
        @keyframes fadeIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
        select,input{outline:none;font-family:'Tajawal',sans-serif}
        ::-webkit-scrollbar{width:3px}::-webkit-scrollbar-thumb{background:rgba(0,214,143,.2);border-radius:2px}
        button{cursor:pointer;font-family:'Tajawal',sans-serif;border:none;background:none}

        /* ===== MOBILE RESPONSIVE (≤640px) — Decision First ===== */
        @media (max-width:640px){
          /* root: scroll instead of fixed overflow:hidden */
          .tm-root{height:auto!important;min-height:100vh;overflow:auto!important}

          /* TOP BAR: shrink, hide market ticks into a compact ticker */
          .tm-topbar{height:48px;padding:0 10px;gap:8px}
          .tm-topbar .tm-mkt{gap:9px;font-size:10px}
          .tm-topbar .tm-mkt span b{font-size:11px}
          .tm-topbar .tm-brand-en{font-size:11px}
          .tm-topbar .tm-brand-sub{font-size:8px}
          .tm-topbar .tm-ny{font-size:9px}

          /* MAIN: single column, verdict first */
          .tm-main{display:block!important;gridTemplateColumns:none!important;overflow:visible!important;gap:0!important;background:#04060A!important}
          .tm-left,.tm-center,.tm-right{overflow:visible!important;padding:12px!important;background:transparent!important}

          /* VERDICT HERO — big & first */
          .tm-verdict{padding:'22px 14px'!important;margin-bottom:12px}
          .tm-verdict .tm-vlabel{font-size:9px;marginBottom:10px}
          .tm-verdict .tm-verdict-en{font-size:30px!important;lineHeight:1.15}
          .tm-verdict .tm-verdict-ar{font-size:17px!important;marginTop:6px}
          .tm-verdict .tm-verdict-reason{font-size:12px!important;marginTop:12px}

          /* compact blocks */
          .tm-card{padding:14px!important;marginBottom:12px}

          /* chart shrinks but still usable */
          .tm-chart-wrap{height:340px!important}
        }
      `}</style>

      {/* TOP BAR */}
      <div className="tm-topbar" style={{height:56,background:'rgba(4,6,10,.97)',backdropFilter:'blur(20px)',borderBottom:'1px solid '+C.border,display:'flex',alignItems:'center',padding:'0 16px',flexShrink:0,gap:14}}>
        <div style={{display:'flex',alignItems:'center',gap:10,flexShrink:0}}>
          <img src={WOLF} alt="THEEB MIND" style={{width:38,height:38,borderRadius:8,objectFit:'cover'}}/>
          <div>
            <div className="tm-brand-en" style={{fontFamily:'JetBrains Mono',fontSize:13,fontWeight:800,color:C.gold,letterSpacing:'.15em',lineHeight:1}}>THEEB MIND</div>
            <div className="tm-brand-sub" style={{fontSize:9,color:C.t3,letterSpacing:'.05em'}}>DECISION GATE</div>
          </div>
        </div>
        <div style={{width:1,height:24,background:C.border}}/>
        <div className="tm-mkt" style={{display:'flex',gap:14,fontFamily:'JetBrains Mono',fontSize:11,color:C.t2,flex:1,overflow:'hidden',alignItems:'center'}}>
          <span>NQ <b style={{color:C.t1}}>18,642.25</b> <span style={{color:C.green}}>+0.62%</span></span>
          {['DXY','VIX','US10Y'].map(inst=>{
            const snap=mktSnaps.find(s=>s.instrument===inst);
            if(!snap)return null;
            const col=snap.direction==='bullish'?C.green:snap.direction==='bearish'?C.red:C.t1;
            return <span key={inst}>{inst} <b style={{color:col}}>{snap.value.toFixed(inst==='US10Y'?2:1)}</b></span>;
          })}
          {macroNarr && (
            <Link to="/market" style={{display:'flex',alignItems:'center',gap:4,padding:'2px 8px',borderRadius:5,background:'rgba(201,168,76,0.12)',border:'1px solid rgba(201,168,76,0.3)',textDecoration:'none',flexShrink:0}}>
              <span style={{fontSize:9,color:C.gold,fontFamily:'JetBrains Mono',fontWeight:700}}>السياق: مُحدَّث ✓</span>
            </Link>
          )}
        </div>
        <div style={{display:'flex',alignItems:'center',gap:8,flexShrink:0}}>
          <span style={{width:6,height:6,borderRadius:'50%',background:C.green,boxShadow:'0 0 6px '+C.green,animation:'pulse 1.8s infinite',display:'inline-block'}}/>
          <span className="tm-ny" style={{fontFamily:'JetBrains Mono',fontSize:10,color:C.gold}}>NY {time}</span>
        </div>
      </div>

      {/* MACRO NARRATIVE BANNER */}
      {macroNarr && (
        <div style={{background:'rgba(201,168,76,0.06)',borderBottom:'1px solid rgba(201,168,76,0.15)',padding:'7px 16px',display:'flex',gap:8,alignItems:'flex-start',flexShrink:0}}>
          <span style={{fontFamily:'JetBrains Mono',fontSize:9,color:C.gold,letterSpacing:'.12em',flexShrink:0,marginTop:1}}>السردية الكلية</span>
          <span style={{fontSize:11,color:C.t2,lineHeight:1.5}}>{macroNarr}</span>
        </div>
      )}

      {/* MAIN — 3 col desktop, 1 col mobile (verdict first) */}
      <div className="tm-main" style={{flex:1,display:'grid',gridTemplateColumns:'230px 1fr 260px',overflow:'hidden',gap:1,background:C.border2}}>

        {/* LEFT */}
        <div className="tm-left" style={{background:C.card,overflow:'auto',padding:'14px',display:'flex',flexDirection:'column',gap:12}}>
          {/* C2 — DECISION GATE */}
          <div className="tm-verdict" style={{padding:'16px 12px',borderRadius:12,textAlign:'center',background:'linear-gradient(160deg,'+verdict.color+'12,transparent)',border:'1.5px solid '+verdict.color+'45',animation:'fadeIn .4s ease'}}>
            <div className="tm-vlabel" style={{fontFamily:'JetBrains Mono',fontSize:8,color:C.t3,letterSpacing:'.2em',marginBottom:8}}>DECISION GATE</div>
            <div className="tm-verdict-en" style={{fontSize:24,fontWeight:900,color:verdict.color,lineHeight:1.25,textShadow:'0 0 24px '+verdict.color+'50'}}>{verdict.verdict}</div>
            <div className="tm-verdict-ar" style={{fontSize:13,color:verdict.color,fontWeight:700,marginTop:4}}>{verdict.ar}</div>
            <div className="tm-verdict-reason" style={{fontSize:10,color:C.t2,marginTop:8,lineHeight:1.5}}>{verdict.reason}</div>
          </div>
          {/* C3 — TRIL */}
          <div style={{padding:'12px',borderRadius:10,background:C.card2,border:'1px solid '+C.border}}>
            <div style={{fontFamily:'JetBrains Mono',fontSize:8,color:C.gold,letterSpacing:'.18em',marginBottom:4}}>TRIL VALIDATION</div>
            <TrilRow label="الاتجاه" en="TREND" pass={trilPass.trend}/>
            <TrilRow label="السيولة" en="RAID" pass={trilPass.raid}/>
            <TrilRow label="عدم التوازن" en="IMBALANCE" pass={trilPass.imbalance}/>
            <TrilRow label="الموقع" en="LOCATION" pass={trilPass.location}/>
            <TrilRow label="كتلة الأوامر" en="ORDER BLOCK" pass={trilPass.orderBlock}/>
            <TrilRow label="إعادة التوازن" en="IMM. REBALANCE" pass={trilPass.immediateRebalance}/>
          </div>
          {/* C4 — QUALITY BREAKDOWN */}
          {(() => {
            const trilFactors = [trilPass.trend, trilPass.raid, trilPass.imbalance, trilPass.location, trilPass.orderBlock, trilPass.immediateRebalance];
            const confNorm   = apiQuality ? Math.round(apiQuality.breakdown.confluence.normalized)  : Math.round((trilFactors.filter(Boolean).length / 6) * 100);
            const psychNorm  = apiQuality ? Math.round(apiQuality.breakdown.psychology.normalized)  : (violations.length === 0 ? 100 : Math.max(20, 100 - violations.length * 20));
            const rrrNorm    = apiQuality ? Math.round(apiQuality.breakdown.quality.normalized)     : Math.min(100, Math.round((rrr / 2.5) * 100));
            const safetyNorm = apiQuality ? Math.round(apiQuality.breakdown.safety.normalized)      : (riskAmount > 500 ? 35 : tradesTaken >= 2 ? 45 : 90);
            const composite  = apiQuality ? apiQuality.composite_score : Math.round(confNorm * 0.30 + psychNorm * 0.25 + rrrNorm * 0.25 + safetyNorm * 0.15);
            const barColor   = (v: number) => v >= 75 ? C.green : v >= 50 ? C.gold : C.red;
            const rows: [string, string, number, number][] = [
              ['التوافق',  'CONFLUENCE', confNorm,  30],
              ['النفسية',  'PSYCHOLOGY', psychNorm, 25],
              ['الجودة',   'QUALITY',    rrrNorm,   25],
              ['الأمان',   'SAFETY',     safetyNorm,15],
            ];
            return (
              <div style={{padding:'12px',borderRadius:10,background:C.card2,border:'1px solid '+C.border}}>
                <div style={{fontFamily:'JetBrains Mono',fontSize:8,color:C.t3,letterSpacing:'.18em',marginBottom:10,display:'flex',justifyContent:'space-between',alignItems:'center'}}>
                  <span>QUALITY BREAKDOWN</span>
                  <span style={{color: composite>=75?C.green:composite>=55?C.gold:C.red,fontWeight:800,fontSize:16}}>{composite}</span>
                </div>
                {rows.map(([ar, en, val, wt])=>(
                  <div key={en} style={{marginBottom:7}}>
                    <div style={{display:'flex',justifyContent:'space-between',marginBottom:2}}>
                      <span style={{fontSize:9,color:C.t2}}>{ar}</span>
                      <span style={{fontFamily:'JetBrains Mono',fontSize:8,color:C.t3}}>{wt}% &middot; <span style={{color:barColor(val)}}>{val}</span></span>
                    </div>
                    <div style={{height:4,background:C.border2,borderRadius:2,overflow:'hidden'}}>
                      <div style={{height:'100%',width:val+'%',background:barColor(val),borderRadius:2,transition:'width .3s ease'}}/>
                    </div>
                  </div>
                ))}
                <div style={{marginTop:8,paddingTop:8,borderTop:'1px solid '+C.border2,display:'flex',justifyContent:'space-between',alignItems:'center'}}>
                  <span style={{fontFamily:'JetBrains Mono',fontSize:8,color:C.t3}}>RRR</span>
                  <span style={{fontFamily:'JetBrains Mono',fontSize:11,fontWeight:800,color:rrr<2.5?C.red:C.t1}}>1:{rrr}</span>
                  <span style={{fontFamily:'JetBrains Mono',fontSize:8,color:C.t3}}>المخاطرة</span>
                  <span style={{fontFamily:'JetBrains Mono',fontSize:11,fontWeight:800,color:riskAmount>500?C.red:C.t1}}>${riskAmount}</span>
                </div>
              </div>
            );
          })()}
          <div style={{fontSize:8.5,color:C.t3,textAlign:'center',marginTop:'auto',lineHeight:1.6}}>تحليل تعليمي — ليس نصيحة مالية</div>
        </div>

        {/* CENTER — C1 CHART + ZONE NOTES */}
        <div className="tm-center" style={{background:C.bg3,display:'flex',flexDirection:'column',overflow:'hidden'}}>

          {/* ── Chart toolbar ── */}
          <div style={{height:36,background:C.card+'ee',borderBottom:'1px solid '+C.border,display:'flex',alignItems:'center',padding:'0 12px',gap:6,flexShrink:0}}>
            {([['NQ100','OANDA:NAS100USD'],['GOLD','OANDA:XAUUSD'],['EUR/USD','FX:EURUSD']] as [string,string][]).map(([l,s])=>(
              <button key={s} onClick={()=>setSymbol(s)} style={{padding:'3px 9px',borderRadius:5,fontSize:10,fontFamily:'JetBrains Mono',fontWeight:700,background:symbol===s?C.gold+'25':'rgba(255,255,255,.03)',color:symbol===s?C.gold:C.t3}}>{l}</button>
            ))}
            <div style={{width:1,height:16,background:C.border}}/>
            {['5','15','60','D'].map(iv=>(
              <button key={iv} onClick={()=>setIvl(iv)} style={{padding:'3px 8px',borderRadius:4,fontSize:10,fontFamily:'JetBrains Mono',background:ivl===iv?C.green+'20':'transparent',color:ivl===iv?C.green:C.t3}}>{iv==='D'?'1D':iv==='60'?'1h':iv+'m'}</button>
            ))}
            <div style={{marginRight:'auto',fontFamily:'JetBrains Mono',fontSize:9,color:C.t3}}>Entry · Stop · Target · Liquidity · OB · FVG · MSS</div>
          </div>

          {/* ── TradingView chart ── */}
          <div className="tm-chart-wrap" style={{flex:1,minHeight:0,overflow:'hidden'}}>
            <iframe
              src={'https://www.tradingview.com/widgetembed/?frameElementId=tv&symbol='+encodeURIComponent(symbol)+'&interval='+ivl+'&theme=dark&style=1&locale=ar&toolbar_bg=0b0a09&hide_side_toolbar=0&allow_symbol_change=1&save_image=0'}
              width="100%" height="100%" style={{display:'block',border:'none'}} title="Educational Chart"
            />
          </div>

          {/* ══════════════════════════════════════════════
              ZONE NOTES — scratch pad for levels / POIs
              ══════════════════════════════════════════════ */}
          <div style={{height:210,borderTop:'1px solid '+C.border,background:C.card,display:'flex',flexDirection:'column',overflow:'hidden',flexShrink:0}}>

            {/* Notes header */}
            <div style={{height:30,background:C.card2,borderBottom:'1px solid '+C.border2,display:'flex',alignItems:'center',justifyContent:'space-between',padding:'0 12px',flexShrink:0}}>
              <span style={{fontFamily:'JetBrains Mono',fontSize:8,color:C.gold,letterSpacing:'.18em'}}>ZONE NOTES · ملاحظات المناطق</span>
              <button
                onClick={()=>{
                  if(!zoneNote.trim()&&!zonePrice.trim()&&zoneTag.length===0)return;
                  const entry={id:Date.now(),tags:[...zoneTag],price:zonePrice,note:zoneNote,time:new Date().toLocaleTimeString('ar-SA',{hour:'2-digit',minute:'2-digit'})};
                  const updated=[entry,...savedZones].slice(0,30);
                  setSavedZones(updated);
                  localStorage.setItem('theeb-zones',JSON.stringify(updated));
                  setZoneNote('');setZonePrice('');setZoneTag([]);
                }}
                style={{padding:'3px 11px',borderRadius:5,background:C.green+'1a',border:'1px solid '+C.green+'44',color:C.green,fontSize:9,fontFamily:'JetBrains Mono',fontWeight:700,cursor:'pointer'}}
              >+ احفظ</button>
            </div>

            {/* Notes body */}
            <div style={{flex:1,display:'flex',overflow:'hidden'}}>

              {/* Input panel */}
              <div style={{width:224,borderLeft:'1px solid '+C.border2,padding:'8px 10px',display:'flex',flexDirection:'column',gap:6,flexShrink:0}}>

                {/* Quick tag chips */}
                <div style={{display:'flex',gap:4,flexWrap:'wrap'}}>
                  {['دعم','مقاومة','FVG','OB','سيولة','POI','MSS','فجوة'].map(tag=>(
                    <button key={tag} onClick={()=>setZoneTag(prev=>prev.includes(tag)?prev.filter(t=>t!==tag):[...prev,tag])}
                      style={{padding:'2px 7px',borderRadius:4,fontSize:9,fontFamily:'JetBrains Mono',fontWeight:700,cursor:'pointer',
                        background:zoneTag.includes(tag)?C.gold+'22':'transparent',
                        border:'1px solid '+(zoneTag.includes(tag)?C.gold+'55':C.border2),
                        color:zoneTag.includes(tag)?C.gold:C.t3,
                        transition:'all .15s ease',
                      }}>{tag}</button>
                  ))}
                </div>

                {/* Price input */}
                <input
                  value={zonePrice} onChange={e=>setZonePrice(e.target.value)}
                  placeholder="السعر / اللفل  e.g. 28,900"
                  style={{padding:'5px 9px',borderRadius:6,background:C.bg3,border:'1px solid '+C.border2,color:C.t1,fontSize:11,fontFamily:'JetBrains Mono',width:'100%',outline:'none'}}
                />

                {/* Notes textarea */}
                <textarea
                  value={zoneNote} onChange={e=>setZoneNote(e.target.value)}
                  placeholder="ملاحظتك عن المنطقة أو اللفل..."
                  style={{flex:1,padding:'6px 9px',borderRadius:6,background:C.bg3,border:'1px solid '+C.border2,color:C.t1,fontSize:11,fontFamily:"'Cairo',sans-serif",resize:'none',lineHeight:1.65,outline:'none',minHeight:0}}
                />
              </div>

              {/* Saved notes list */}
              <div style={{flex:1,overflow:'auto',padding:'6px 10px',display:'flex',flexDirection:'column',gap:5}}>
                {savedZones.length===0?(
                  <div style={{display:'flex',flexDirection:'column',alignItems:'center',justifyContent:'center',height:'100%',gap:6,opacity:.45}}>
                    <span style={{fontSize:18,lineHeight:1}}>📍</span>
                    <span style={{fontSize:10,color:C.t3,fontFamily:"'Cairo',sans-serif",textAlign:'center'}}>لا توجد ملاحظات بعد<br/>سجّل أول منطقة من الشارت</span>
                  </div>
                ):savedZones.map(z=>(
                  <div key={z.id} style={{padding:'7px 9px',borderRadius:7,background:C.card2,border:'1px solid '+C.border2,display:'flex',flexDirection:'column',gap:4,flexShrink:0,transition:'border-color .2s'}}>
                    <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',gap:6}}>
                      <div style={{display:'flex',gap:4,flexWrap:'wrap',flex:1}}>
                        {z.tags.map(t=>(
                          <span key={t} style={{fontSize:8,color:C.gold,fontFamily:'JetBrains Mono',fontWeight:700,background:C.gold+'18',padding:'1px 5px',borderRadius:3}}>{t}</span>
                        ))}
                        {z.price&&<span style={{fontSize:8,color:C.green,fontFamily:'JetBrains Mono',fontWeight:700,background:C.green+'14',padding:'1px 5px',borderRadius:3}}>{z.price}</span>}
                      </div>
                      <div style={{display:'flex',alignItems:'center',gap:8,flexShrink:0}}>
                        <span style={{fontSize:8,color:C.t3,fontFamily:'JetBrains Mono'}}>{z.time}</span>
                        <button onClick={()=>{const u=savedZones.filter(s=>s.id!==z.id);setSavedZones(u);localStorage.setItem('theeb-zones',JSON.stringify(u));}}
                          style={{fontSize:9,color:C.t3,cursor:'pointer',background:'none',border:'none',padding:'0 2px',lineHeight:1}}
                          onMouseEnter={e=>(e.currentTarget.style.color=C.red)}
                          onMouseLeave={e=>(e.currentTarget.style.color=C.t3)}
                        >✕</button>
                      </div>
                    </div>
                    {z.note&&<div style={{fontSize:11,color:C.t2,lineHeight:1.65,fontFamily:"'Cairo',sans-serif"}}>{z.note}</div>}
                  </div>
                ))}
              </div>

            </div>
          </div>

        </div>

        {/* RIGHT — C5 CONTROLS + THEEB COACH */}
        <div className="tm-right" style={{background:C.card,overflow:'auto',padding:'14px',display:'flex',flexDirection:'column',gap:12}}>
          {/* قراءة الشارت — inputs moved here so verdict reacts immediately */}
          <div style={{padding:'10px 12px',borderRadius:10,background:C.card2,border:'1px solid '+C.border}}>
            <div style={{fontFamily:'JetBrains Mono',fontSize:8,color:C.t3,letterSpacing:'.14em',marginBottom:8}}>قراءة الشارت</div>
            <div style={{display:'flex',gap:5,flexWrap:'wrap',marginBottom:8}}>
              <Toggle label={trend==='bullish'?'صاعد':trend==='bearish'?'هابط':'محايد'} active={trend!=='neutral'} onToggle={()=>setTrend(trendCycle[(trendCycle.indexOf(trend)+1)%3])}/>
              <Toggle label={raid?'Raid ✓':'Raid ✕'} active={raid} onToggle={()=>setRaid(!raid)}/>
              <Toggle label={imbalance?'FVG ✓':'FVG ✕'} active={imbalance} onToggle={()=>setImbalance(!imbalance)}/>
              <Toggle label={location==='discount'?'Discount':location==='premium'?'Premium':'Equilib'} active={location!=='equilibrium'} onToggle={()=>setLocation(locCycle[(locCycle.indexOf(location)+1)%3])}/>
              <Toggle label={orderBlock?'OB ✓':'OB ✕'} active={orderBlock} onToggle={()=>setOrderBlock(!orderBlock)}/>
              <Toggle label={immediateRebalance?'ImmReb ✓':'ImmReb ✕'} active={immediateRebalance} onToggle={()=>setImmediateRebalance(!immediateRebalance)}/>
            </div>
            <div style={{fontSize:9,color:C.t3,marginBottom:3}}>صفقات اليوم: {tradesTaken}/2</div>
            <input type="range" min={0} max={3} value={tradesTaken} onChange={e=>setTradesTaken(+e.target.value)} style={{width:'100%',height:3,accentColor:tradesTaken>=2?C.red:C.green,marginBottom:8}}/>
            <div style={{fontSize:9,color:C.t3,marginBottom:3}}>RRR: 1:{rrr}</div>
            <input type="range" min={1} max={4} step={0.5} value={rrr} onChange={e=>setRrr(+e.target.value)} style={{width:'100%',height:3,accentColor:rrr<2.5?C.red:C.green}}/>
          </div>
          <div style={{padding:'14px',borderRadius:10,background:'linear-gradient(160deg,rgba(8,14,20,.97),rgba(4,8,14,1))',border:'1px solid '+C.border,flex:1,animation:'fadeIn .5s ease'}}>
            <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:12}}>
              <img src={WOLF} alt="" style={{width:22,height:22,borderRadius:5,objectFit:'cover'}}/>
              <div style={{fontFamily:'JetBrains Mono',fontSize:9,color:C.gold,letterSpacing:'.16em',fontWeight:700}}>THEEB COACH</div>
            </div>
            <div style={{display:'flex',flexDirection:'column',gap:9}}>
              {coach.map((line,i)=>(
                <div key={i} style={{fontSize:13,lineHeight:1.7,color:i===0?C.t1:C.t2,fontWeight:i===0?700:400,paddingRight:10,borderRight:i===0?'2px solid '+verdict.color:'2px solid '+C.border2}}>{line}</div>
              ))}
            </div>
          </div>
          <div style={{padding:'12px',borderRadius:10,background:C.card2,border:'1px solid '+C.border}}>
            <div style={{fontFamily:'JetBrains Mono',fontSize:8,color:C.t3,letterSpacing:'.16em',marginBottom:8}}>THEEB CONSTITUTION</div>
            {violations.length===0?(
              <div style={{fontSize:11,color:C.green,display:'flex',alignItems:'center',gap:6}}><span>✓</span> كل القواعد محترمة</div>
            ):(
              violations.map((v,i)=>(
                <div key={i} style={{fontSize:10.5,color:C.red,marginBottom:4,display:'flex',gap:6,alignItems:'flex-start'}}><span style={{flexShrink:0}}>✕</span><span>{v}</span></div>
              ))
            )}
          </div>
          <div style={{fontSize:8.5,color:C.t3,textAlign:'center',lineHeight:1.6}}>"لا تتنبأ بالسوق. افهم قراراتك."</div>
        </div>
      </div>
    </div>
  );
}
